<template>
  <div class="p-15" style="overflow: auto; height: 100%">
    <el-form :inline="true" :model="attributeParams" size="small">
      <el-form-item>
        <el-select
          v-model="attributeParams.source_id"
          placeholder="请选择设备"
          clearable
        >
          <el-option
            v-for="item in deviceList"
            :key="item.id"
            :label="item.source_name"
            :value="item.id"
          ></el-option>
        </el-select>
      </el-form-item>
      <el-form-item>
        <el-button type="primary" @click="query">查询</el-button>
        <el-button @click="reset">重置</el-button>
      </el-form-item>
    </el-form>
    <el-tabs v-model="activeName" @tab-click="handleClick">
      <el-tab-pane label="数据记录" name="1"> </el-tab-pane>
      <el-tab-pane label="报警记录" name="2"> </el-tab-pane>
      <!-- <el-tab-pane label="视频录像" name="3"> </el-tab-pane> -->
      <records
        :chooseItem="chooseItem"
        ref="recordsRef"
        :activeName="activeName"
        :recordsList="recordsList"
        :AiValueList="AiValueList"
      ></records>
      <pagination
        class="float-right mt-10 mb-10"
        v-show="aiTotal > 0"
        :total="aiTotal"
        :page.sync="attributeParams.page"
        :limit.sync="attributeParams.size"
        @pagination="activeName == '2' ? getDataList() : getDataAiValueList()"
        layout="total, prev, pager, next"
        small
      />
    </el-tabs>
  </div>
</template>

<script>
import records from "./components/records/Modbus.vue";
export default {
  components: {
    records,
  },
  data() {
    return {
      recordsList: [],
      chooseItem: {},
      attributeParams: {
        page: 1,
        size: 10,
        source_id: "",
      },
      activeName: "1",
      expandedKeys: [],
      checkedKeys: [],
      AiValueList: [],
      aiTotal: 0,
      deviceList: [],
    };
  },
  created() {
    this.getDeviceList();
  },
  mounted() {
    this.setStyle();
  },
  filters: {
    toFixed(value) {
      return Number(value).toFixed(2);
    },
  },
  methods: {
    query() {
      let e = {
        index: this.activeName == "1" ? "0" : "1",
      };
      this.handleClick(e);
    },
    reset() {
      this.attributeParams.source_id = this.deviceList[0].id;
      this.query();
    },
    getDeviceList() {
      this.$api.get(`/collect/getDataSourceList`).then((res) => {
        if (res.data.data) {
          this.deviceList = res.data.data.filter(
            (item) => item.driver_protocol != 1 && item.driver_protocol != 2
          );
          this.attributeParams.source_id = this.deviceList[0].id;
          this.query();
        }
      });
    },
    parsedData(row) {
      try {
        return JSON.parse(row.ai_value) || [];
      } catch (e) {
        console.error("解析ai_value失败:", e);
        return [];
      }
    },
    shouldShowMore(row) {
      return this.parsedData(row).length > 4;
    },
    getDataAiValueList() {
      this.$api
        .get(`/collect/getDataRecordList`, {
          params: this.attributeParams,
        })
        .then((res) => {
          if (res.data.data) {
            this.AiValueList = res.data.data;
            this.aiTotal = res.data.total;
          } else {
            this.AiValueList = [];
          }
        });
    },
    getDataList() {
      this.$api
        .get(`/ai/getDataAiRecordList`, {
          params: this.attributeParams,
        })
        .then((res) => {
          if (res.data.data) {
            this.recordsList = res.data.data;
            this.aiTotal = res.data.total;
          } else {
            this.aiTotal = 0;
            this.recordsList = [];
          }
        });
    },

    handleClick(e) {
      this.recordsList = []; // 清空报警记录数据
      this.AiValueList = []; // 清空数据记录数据
      this.aiTotal = 0;
      this.attributeParams.page = 1;
      if (e.index == "0") {
        this.getDataAiValueList();
      } else {
        this.getDataList();
      }
    },

    setStyle() {
      const elMain = document.querySelector(".el-main");
      if (elMain) {
        elMain.style.padding = "0px";
        elMain.style.overflow = "hidden";
      }
    },
    getAttributeList() {},
  },
  beforeDestroy() {
    const elMain = document.querySelector(".el-main");
    if (elMain) {
      elMain.style.padding = "20px";
      elMain.style.overflow = "auto";
    }
  },
};
</script>

<style lang="scss" scoped>
.tree {
  width: 14vw;
  border-right: 5px solid #f4f4f4;
  height: 100%;
  padding: 15px;
}
</style>
